import hashlib
import hmac
import os
import time
import threading
from flask import Flask, request, jsonify, g
from functools import wraps
import sqlite3
import re

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
app.config['DATABASE'] = os.environ.get('DATABASE', ':memory:')

_session_store = {}
_store_lock = threading.Lock()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT "user")')
        g.db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT, content TEXT, classification TEXT DEFAULT "public")')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def create_session(user_id, role):
    token = hashlib.sha256(os.urandom(32)).hexdigest()
    with _store_lock:
        _session_store[token] = {
            'user_id': user_id,
            'role': role,
            'created_at': time.time(),
            'last_verified': time.time()
        }
    return token

def get_session_data(token):
    with _store_lock:
        session = _session_store.get(token)
        if session:
            return dict(session)
    return None

def update_session_verification(token):
    with _store_lock:
        if token in _session_store:
            _session_store[token]['last_verified'] = time.time()

def invalidate_session(token):
    with _store_lock:
        _session_store.pop(token, None)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token', '')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401
        session = get_session_data(token)
        if not session:
            return jsonify({'error': 'Invalid session'}), 401
        if time.time() - session['created_at'] > 3600:
            invalidate_session(token)
            return jsonify({'error': 'Session expired'}), 401
        g.current_user_id = session['user_id']
        g.current_role = session['role']
        g.session_token = token
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            # Always re-read role from database for authorization decisions
            db = get_db()
            user = db.execute('SELECT role FROM users WHERE id = ?', (g.current_user_id,)).fetchone()
            if not user or user['role'] != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    username = data['username']
    password = data['password']
    if not re.match(r'^[a-zA-Z0-9_]{3,30}$', username):
        return jsonify({'error': 'Invalid username'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400
    import bcrypt
    password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
                   (username, password_hash, 'user'))
        db.commit()
        return jsonify({'message': 'User created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username taken'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (data['username'],)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401
    import bcrypt
    if not bcrypt.checkpw(data['password'].encode(), user['password_hash'].encode()):
        return jsonify({'error': 'Invalid credentials'}), 401
    token = create_session(user['id'], user['role'])
    return jsonify({'token': token, 'role': user['role']})

@app.route('/api/promote', methods=['POST'])
@require_auth
@require_role('admin')
def promote_user():
    data = request.get_json()
    if not data or 'user_id' not in data or 'new_role' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    if data['new_role'] not in ('user', 'moderator', 'admin'):
        return jsonify({'error': 'Invalid role'}), 400
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (data['new_role'], data['user_id']))
    db.commit()
    return jsonify({'message': 'User promoted'})

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    classification = data.get('classification', 'public')
    if classification not in ('public', 'internal', 'confidential'):
        classification = 'public'
    db = get_db()
    db.execute('INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
               (g.current_user_id, data['title'], data['content'], classification))
    db.commit()
    return jsonify({'message': 'Document created'}), 201

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'Not found'}), 404
    if doc['classification'] == 'confidential':
        # Re-read current role from DB for access control
        user = db.execute('SELECT role FROM users WHERE id = ?', (g.current_user_id,)).fetchone()
        current_role = user['role'] if user else 'user'
        if current_role not in ('admin', 'moderator') and doc['owner_id'] != g.current_user_id:
            return jsonify({'error': 'Access denied'}), 403
    elif doc['classification'] == 'internal':
        pass  # Any authenticated user can access internal docs
    return jsonify({
        'id': doc['id'],
        'title': doc['title'],
        'content': doc['content'],
        'classification': doc['classification'],
        'owner_id': doc['owner_id']
    })

@app.route('/api/role-change', methods=['POST'])
@require_auth
def request_role_change():
    """User requests a role change - admin reviews asynchronously.
    This endpoint validates the request and queues it."""
    data = request.get_json()
    if not data or 'requested_role' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    requested = data['requested_role']
    if requested not in ('moderator',):
        return jsonify({'error': 'Can only request moderator role'}), 400
    # Store the request for admin review
    db = get_db()
    db.execute('CREATE TABLE IF NOT EXISTS role_requests (id INTEGER PRIMARY KEY, user_id INTEGER, requested_role TEXT, status TEXT DEFAULT "pending")')
    db.execute('INSERT INTO role_requests (user_id, requested_role) VALUES (?, ?)',
               (g.current_user_id, requested))
    db.commit()
    return jsonify({'message': 'Request submitted'})

@app.route('/api/admin/approve-role/<int:request_id>', methods=['POST'])
@require_auth
@require_role('admin')
def approve_role_change(request_id):
    db = get_db()
    req = db.execute('SELECT * FROM role_requests WHERE id = ? AND status = "pending"', (request_id,)).fetchone()
    if not req:
        return jsonify({'error': 'Request not found'}), 404
    # Update user role
    db.execute('UPDATE users SET role = ? WHERE id = ?', (req['requested_role'], req['user_id']))
    db.execute('UPDATE role_requests SET status = "approved" WHERE id = ?', (request_id,))
    db.commit()
    # Update any active sessions for this user
    with _store_lock:
        for token, session in _session_store.items():
            if session['user_id'] == req['user_id']:
                session['role'] = req['requested_role']
    return jsonify({'message': 'Role change approved'})

@app.route('/api/admin/revoke-role/<int:user_id>', methods=['POST'])
@require_auth
@require_role('admin')
def revoke_role(user_id):
    db = get_db()
    db.execute('UPDATE users SET role = "user" WHERE id = ?', (user_id,))
    db.commit()
    # Atomically revoke role in all active sessions
    with _store_lock:
        for token, session in _session_store.items():
            if session['user_id'] == user_id:
                session['role'] = 'user'
    return jsonify({'message': 'Role revoked'})

@app.route('/api/session/refresh', methods=['POST'])
@require_auth
def refresh_session():
    """Refresh session - re-reads role from database to ensure consistency."""
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE id = ?', (g.current_user_id,)).fetchone()
    if not user:
        invalidate_session(g.session_token)
        return jsonify({'error': 'User not found'}), 401
    # Update session with current DB role
    with _store_lock:
        if g.session_token in _session_store:
            _session_store[g.session_token]['role'] = user['role']
            _session_store[g.session_token]['last_verified'] = time.time()
    return jsonify({'role': user['role'], 'refreshed': True})

if __name__ == '__main__':
